def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
                        seen.add((a,b)); stack.append((a,b))
            mr=min(x for x,y in cells); mc=min(y for x,y in cells)
            key=tuple(sorted((x-mr,y-mc) for x,y in cells))
            objects.append((key,cells))
    counts=Counter(key for key,cells in objects)
    out=[[0]*w for _ in range(h)]
    for key,cells in objects:
        if counts[key]>1:
            for r,c in cells: out[r][c]=grid[r][c]
    return out

